module.exports = [
{ e: "🐦", art: { b: "🐦", s: ["🪶", "☁️", "🌤️", "🦅"], c: ["#1B3A6B", "#4A8AD4"] },
pt: { h: "O vovô transformou uma caixa de papelão gigante numa cabine de avião, com botões desenhados e um volante de prato. “Bem-vindos à Escola de Voo!”, anunciou. “Cada noite, uma aula e um carimbo na caderneta de voo.” Nina e Leo se sentaram, e o Pipoca virou o copiloto.", t: "O sonho de voar", f: "Desde sempre, as pessoas olhavam os pássaros e sonhavam em voar. Mas nosso corpo não foi feito para isso: somos pesados demais e nossos braços não têm força suficiente para bater asas e levantar o corpo.", x: "Os pássaros têm ossos ocos e leves, e os músculos do peito, que movem as asas, podem ser uma boa parte do peso deles. Um beija-flor bate as asas dezenas de vezes por segundo!", s: ["Há uma lenda grega sobre Ícaro, que fez asas de penas e cera e voou perto demais do Sol.", "Durante séculos, muitas pessoas amarraram asas nos braços e pularam de torres, sem sucesso.", "Para voar, os humanos precisaram entender o ar e inventar máquinas."], ex: { t: "Folha lisa x bolinha", m: "duas folhas de papel iguais", p: ["Amasse uma das folhas até virar uma bolinha. A outra fica lisinha.", "Segure as duas na mesma altura e solte ao mesmo tempo.", "A bolinha cai rápido, e a folha lisa desce balançando! O ar empurra mais a folha aberta. Os aviões usam o ar a seu favor."] }, at: "Minha caderneta de voo", m: "um caderninho, lápis de cor, carimbo ou adesivos", p: ["Faça a capa da sua caderneta de voo com seu nome e uma foto ou desenho seu de piloto.", "Na primeira página, desenhe o pássaro que você acha que voa mais bonito.", "Ganhe seu primeiro carimbo ou adesivo de voo!"], q: "Se você pudesse ter as asas de um pássaro, qual escolheria?" },
en: { h: "Grandpa turned a giant cardboard box into an airplane cockpit, with drawn-on buttons and a paper-plate steering wheel. “Welcome to Flight School!” he announced. “Every night, one lesson and one stamp in your flight logbook.” Nina and Leo sat down, and Popcorn became the copilot.", t: "The dream of flying", f: "People have always watched birds and dreamed of flying. But our bodies aren't built for it: we're too heavy, and our arms aren't strong enough to flap wings and lift our bodies.", x: "Birds have hollow, light bones, and the chest muscles that move their wings can make up a big part of their weight. A hummingbird beats its wings dozens of times per second!", s: ["There's a Greek legend about Icarus, who made wings of feathers and wax and flew too close to the Sun.", "For centuries, many people strapped wings to their arms and jumped off towers, without success.", "To fly, humans had to understand the air and invent machines."], ex: { t: "Flat sheet vs. paper ball", m: "two identical sheets of paper", p: ["Crumple one sheet into a ball. Leave the other flat.", "Hold both at the same height and let go at the same time.", "The ball drops fast, and the flat sheet floats down swaying! Air pushes harder on the open sheet. Airplanes use the air to their advantage."] }, at: "My flight logbook", m: "a small notebook, colored pencils, a stamp or stickers", p: ["Make the cover of your flight logbook with your name and a photo or drawing of you as a pilot.", "On the first page, draw the bird you think flies most beautifully.", "Earn your first flight stamp or sticker!"], q: "If you could have the wings of a bird, which would you choose?" },
es: { h: "El abuelo convirtió una caja de cartón gigante en una cabina de avión, con botones dibujados y un volante hecho con un plato. “¡Bienvenidos a la Escuela de Vuelo!”, anunció. “Cada noche, una clase y un sello en la libreta de vuelo.” Nina y Leo se sentaron, y Palomita se convirtió en el copiloto.", t: "El sueño de volar", f: "Desde siempre, las personas miraban a los pájaros y soñaban con volar. Pero nuestro cuerpo no está hecho para eso: somos demasiado pesados y nuestros brazos no tienen fuerza suficiente para batir alas y levantar el cuerpo.", x: "¡Los pájaros tienen huesos huecos y livianos, y los músculos del pecho, que mueven las alas, pueden ser una buena parte de su peso. Un colibrí bate las alas decenas de veces por segundo!", s: ["Hay una leyenda griega sobre Ícaro, que hizo alas de plumas y cera y voló demasiado cerca del Sol.", "Durante siglos, muchas personas se ataron alas a los brazos y saltaron de torres, sin éxito.", "Para volar, los humanos tuvieron que entender el aire e inventar máquinas."], ex: { t: "Hoja lisa vs. bollito", m: "dos hojas de papel iguales", p: ["Arruga una de las hojas hasta hacer un bollito. La otra queda lisa.", "Sostén las dos a la misma altura y suéltalas al mismo tiempo.", "¡El bollito cae rápido y la hoja lisa baja balanceándose! El aire empuja más a la hoja abierta. Los aviones usan el aire a su favor."] }, at: "Mi libreta de vuelo", m: "un cuadernito, lápices de colores, un sello o stickers", p: ["Haz la tapa de tu libreta de vuelo con tu nombre y una foto o dibujo tuyo como piloto.", "En la primera página, dibuja el pájaro que te parece que vuela más lindo.", "¡Gana tu primer sello o sticker de vuelo!"], q: "Si pudieras tener las alas de un pájaro, ¿cuáles elegirías?" } },

{ e: "🪂", art: { b: "🪂", s: ["✏️", "📜", "🌀", "🦇"], c: ["#3A2A1B", "#A07A4A"] },
pt: { h: "Nina encontrou num livro uns desenhos antigos de máquinas com asas de morcego e parafusos gigantes. “Quem desenhou isso?”, perguntou. “Leonardo da Vinci, há mais de 500 anos”, respondeu o vovô. “Ele também desenhou um paraquedas, muito antes de alguém precisar de um!”", t: "As máquinas voadoras de Leonardo", f: "Leonardo da Vinci, o pintor da Mona Lisa, também era inventor. Ele estudou o voo dos pássaros e desenhou máquinas voadoras com asas que batiam, um “parafuso aéreo” parecido com um helicóptero e um paraquedas em forma de pirâmide.", x: "Em 2000, um paraquedista construiu o paraquedas de Leonardo seguindo o desenho original e saltou com ele. Funcionou!", s: ["Leonardo escrevia suas anotações ao contrário, da direita para a esquerda, como num espelho.", "Ele encheu cadernos inteiros com estudos sobre como os pássaros voam.", "Suas máquinas voadoras não chegaram a ser construídas na época, mas as ideias inspiraram inventores depois."], ex: { t: "Paraquedas de sacolinha", m: "uma sacola plástica, barbante, fita adesiva, um bonequinho leve", p: ["Recorte um quadrado da sacola e prenda um barbante em cada canto com fita.", "Junte as quatro pontas dos barbantes e amarre o bonequinho.", "Solte de um lugar alto (com um adulto): o ar enche o paraquedas e o boneco desce devagar! Compare com o boneco sem paraquedas."] }, at: "Caderno de inventor", m: "papel, lápis", p: ["Observe um pássaro, um inseto ou uma folha voando e desenhe com calma.", "Invente uma máquina voadora inspirada nele.", "Tente escrever o nome dela ao contrário, como Leonardo, e cole o carimbo do dia."], q: "Que animal você usaria de inspiração para inventar uma máquina?" },
en: { h: "Nina found some old drawings in a book of machines with bat-like wings and giant screws. “Who drew these?” she asked. “Leonardo da Vinci, more than 500 years ago,” Grandpa answered. “He also drew a parachute, long before anyone needed one!”", t: "Leonardo's flying machines", f: "Leonardo da Vinci, the painter of the Mona Lisa, was also an inventor. He studied how birds fly and drew flying machines with flapping wings, an “aerial screw” that looked like a helicopter and a pyramid-shaped parachute.", x: "In 2000, a skydiver built Leonardo's parachute following the original drawing and jumped with it. It worked!", s: ["Leonardo wrote his notes backward, from right to left, like in a mirror.", "He filled whole notebooks with studies of how birds fly.", "His flying machines weren't built in his time, but his ideas inspired later inventors."], ex: { t: "Plastic bag parachute", m: "a plastic bag, string, tape, a small light toy", p: ["Cut a square from the bag and tape a piece of string to each corner.", "Gather the four string ends and tie on the toy.", "Drop it from somewhere high (with a grown-up): the air fills the parachute and the toy floats down slowly! Compare with the toy without a parachute."] }, at: "Inventor's notebook", m: "paper, pencil", p: ["Watch a bird, an insect or a leaf in the air and draw it carefully.", "Invent a flying machine inspired by it.", "Try writing its name backward, like Leonardo, and add today's stamp."], q: "What animal would you use as inspiration for an invention?" },
es: { h: "Nina encontró en un libro unos dibujos antiguos de máquinas con alas de murciélago y tornillos gigantes. “¿Quién dibujó esto?”, preguntó. “Leonardo da Vinci, hace más de 500 años”, respondió el abuelo. “¡También dibujó un paracaídas, mucho antes de que alguien lo necesitara!”", t: "Las máquinas voladoras de Leonardo", f: "Leonardo da Vinci, el pintor de la Mona Lisa, también era inventor. Estudió el vuelo de los pájaros y dibujó máquinas voladoras con alas que se batían, un “tornillo aéreo” parecido a un helicóptero y un paracaídas en forma de pirámide.", x: "¡En el año 2000, un paracaidista construyó el paracaídas de Leonardo siguiendo el dibujo original y saltó con él. Funcionó!", s: ["Leonardo escribía sus notas al revés, de derecha a izquierda, como en un espejo.", "Llenó cuadernos enteros con estudios sobre cómo vuelan los pájaros.", "Sus máquinas voladoras no se construyeron en su época, pero sus ideas inspiraron a inventores después."], ex: { t: "Paracaídas de bolsita", m: "una bolsa de plástico, cordel, cinta adhesiva, un muñequito liviano", p: ["Recorta un cuadrado de la bolsa y pega un cordel en cada esquina con cinta.", "Junta las cuatro puntas de los cordeles y ata el muñequito.", "Suéltalo desde un lugar alto (con un adulto): ¡el aire llena el paracaídas y el muñeco baja despacio! Compáralo con el muñeco sin paracaídas."] }, at: "Cuaderno de inventor", m: "papel, lápiz", p: ["Observa un pájaro, un insecto o una hoja en el aire y dibújalo con calma.", "Inventa una máquina voladora inspirada en él.", "Intenta escribir su nombre al revés, como Leonardo, y pon el sello del día."], q: "¿Qué animal usarías como inspiración para inventar una máquina?" } },

{ e: "🎈", art: { b: "🎈", s: ["🔥", "🐑", "🦆", "🐓"], c: ["#5A1B1B", "#E0603A"] },
pt: { h: "Leo soltou uma bexiga de festa e ficou triste quando ela não subiu. O vovô explicou que, para subir, um balão precisa de algo mais leve que o ar dentro dele. “Os primeiros balões usavam ar quente”, disse. “E um dos primeiros a mostrar isso nasceu aqui no Brasil!”", t: "Os primeiros balões", f: "O ar quente é mais leve que o ar frio e por isso sobe. Em 1709, o padre Bartolomeu de Gusmão, nascido em Santos, mostrou ao rei de Portugal um pequeno balão de ar quente que subiu dentro do palácio. Em 1783, na França, os irmãos Montgolfier fizeram balões grandes que levaram pessoas ao céu.", x: "Os primeiros passageiros de um balão foram uma ovelha, um pato e um galo, em 1783! Só depois deu para ter certeza de que pessoas poderiam voar em segurança.", s: ["Bartolomeu de Gusmão ficou conhecido como “o padre voador”.", "Em novembro de 1783, duas pessoas voaram num balão sobre Paris por uns 25 minutos.", "Hoje existem festivais de balões que enchem o céu de cores, inclusive no Brasil."], ex: { t: "Bexiga que enche com calor", m: "uma garrafa de plástico vazia, uma bexiga, uma tigela com água quente da torneira (com um adulto)", p: ["Encaixe a bexiga murcha na boca da garrafa vazia.", "Coloque a garrafa dentro da tigela com água quente.", "A bexiga começa a encher sozinha! O ar dentro da garrafa esquenta, se expande e sobe. Tire a garrafa da água e veja ela murchar de novo."] }, at: "Balão colorido", m: "papel, lápis de cor, barbante", p: ["Desenhe um balão de ar quente bem colorido, com um cesto embaixo.", "Desenhe dentro do cesto a ovelha, o pato e o galo, os primeiros passageiros.", "Pendure no quarto com barbante e carimbe a caderneta."], q: "Você teria coragem de voar num balão? Para onde iria?" },
en: { h: "Leo let go of a party balloon and was sad when it didn't rise. Grandpa explained that to go up, a balloon needs something lighter than air inside. “The first balloons used hot air,” he said. “And one of the first people to show this was born in Brazil!”", t: "The first balloons", f: "Hot air is lighter than cold air, so it rises. In 1709, Father Bartolomeu de Gusmão, born in Santos, Brazil, showed the king of Portugal a small hot-air balloon that floated up inside the palace. In 1783, in France, the Montgolfier brothers built large balloons that carried people into the sky.", x: "The first balloon passengers were a sheep, a duck and a rooster, in 1783! Only after that were people sure humans could fly safely.", s: ["Bartolomeu de Gusmão became known as “the flying priest.”", "In November 1783, two people flew in a balloon over Paris for about 25 minutes.", "Today there are balloon festivals that fill the sky with color, including in Brazil."], ex: { t: "Balloon that inflates with heat", m: "an empty plastic bottle, a balloon, a bowl of hot tap water (with a grown-up)", p: ["Stretch the deflated balloon over the mouth of the empty bottle.", "Place the bottle in the bowl of hot water.", "The balloon starts to inflate by itself! The air in the bottle warms up, expands and rises. Take the bottle out of the water and watch the balloon shrink again."] }, at: "Colorful balloon", m: "paper, colored pencils, string", p: ["Draw a very colorful hot-air balloon with a basket underneath.", "Inside the basket, draw the sheep, the duck and the rooster, the first passengers.", "Hang it in your room with string and stamp your logbook."], q: "Would you be brave enough to fly in a balloon? Where would you go?" },
es: { h: "Leo soltó un globo de fiesta y se puso triste cuando no subió. El abuelo explicó que, para subir, un globo necesita algo más liviano que el aire adentro. “Los primeros globos usaban aire caliente”, dijo. “¡Y uno de los primeros en demostrarlo nació en Brasil!”", t: "Los primeros globos", f: "El aire caliente es más liviano que el aire frío y por eso sube. En 1709, el padre Bartolomeu de Gusmão, nacido en Santos, Brasil, le mostró al rey de Portugal un pequeño globo de aire caliente que subió dentro del palacio. En 1783, en Francia, los hermanos Montgolfier hicieron globos grandes que llevaron personas al cielo.", x: "¡Los primeros pasajeros de un globo fueron una oveja, un pato y un gallo, en 1783! Solo después se supo con seguridad que las personas podían volar sin peligro.", s: ["Bartolomeu de Gusmão fue conocido como “el padre volador”.", "En noviembre de 1783, dos personas volaron en globo sobre París durante unos 25 minutos.", "Hoy hay festivales de globos que llenan el cielo de colores, también en América Latina."], ex: { t: "Globo que se infla con calor", m: "una botella de plástico vacía, un globo, un tazón con agua caliente de la canilla (con un adulto)", p: ["Coloca el globo desinflado en la boca de la botella vacía.", "Pon la botella dentro del tazón con agua caliente.", "¡El globo empieza a inflarse solo! El aire de la botella se calienta, se expande y sube. Saca la botella del agua y mira cómo se desinfla otra vez."] }, at: "Globo de colores", m: "papel, lápices de colores, cordel", p: ["Dibuja un globo de aire caliente bien colorido, con una canasta abajo.", "Dentro de la canasta dibuja la oveja, el pato y el gallo, los primeros pasajeros.", "Cuélgalo en tu cuarto con un cordel y sella tu libreta."], q: "¿Te animarías a volar en globo? ¿Adónde irías?" } },

{ e: "🪁", art: { b: "🪁", s: ["⛰️", "🌬️", "🦅", "🧔"], c: ["#1B4E3A", "#4AA07A"] },
pt: { h: "No alto de um morro, Nina e Leo viram uma pessoa pulando com uma asa enorme e flutuando devagarinho até lá embaixo, sem motor nenhum. “Como ela não cai?”, perguntou Leo. “Ela plana, como os urubus”, respondeu o vovô. “Foi assim que os inventores aprenderam a controlar o voo.”", t: "Os planadores", f: "Um planador é uma aeronave sem motor que desliza pelo ar, descendo devagar. No século 19, o inglês George Cayley descobriu as forças que agem num avião e construiu planadores. Depois, o alemão Otto Lilienthal fez cerca de 2 mil voos com planadores que ele mesmo construiu.", x: "Otto Lilienthal foi chamado de “rei dos planadores”. Os irmãos Wright estudaram tudo o que ele anotou antes de construir o avião deles!", s: ["Os planadores sobem usando correntes de ar quente que vêm do chão, como fazem os urubus e as águias.", "George Cayley desenhou um avião com asa fixa, cauda e corpo separados, muito parecido com os aviões de hoje.", "Até hoje existem pilotos de planador, e eles conseguem ficar horas no ar."], ex: { t: "Planador de argolas", m: "um canudo, uma tira de cartolina de 2 x 12 cm, outra de 2 x 20 cm, fita adesiva", p: ["Faça uma argola com cada tira de cartolina, prendendo as pontas com fita.", "Prenda a argola pequena numa ponta do canudo e a grande na outra.", "Lance com a argola pequena na frente, com um empurrão suave: ele plana longe! As argolas funcionam como asas."] }, at: "Campeonato de planadores", m: "papel, fita métrica ou passos", p: ["Faça seu planador de argolas e um avião de papel comum.", "Lance cada um três vezes e meça qual vai mais longe.", "Anote os resultados na caderneta e ganhe o carimbo do dia."], q: "Que animal você já viu planando no céu?" },
en: { h: "On top of a hill, Nina and Leo saw a person jump with a huge wing and float slowly all the way down, with no engine at all. “How doesn't she fall?” Leo asked. “She glides, like vultures do,” Grandpa answered. “That's how inventors learned to control flight.”", t: "Gliders", f: "A glider is an aircraft without an engine that slides through the air, slowly coming down. In the 1800s, Englishman George Cayley figured out the forces that act on an airplane and built gliders. Later, German Otto Lilienthal made about 2,000 flights in gliders he built himself.", x: "Otto Lilienthal was called “the Glider King.” The Wright brothers studied everything he wrote down before building their airplane!", s: ["Gliders climb using columns of warm air rising from the ground, just like vultures and eagles do.", "George Cayley designed an airplane with fixed wings, a tail and a separate body, very much like today's planes.", "There are still glider pilots today, and they can stay in the air for hours."], ex: { t: "Hoop glider", m: "a straw, a strip of card 2 x 12 cm (1 x 5 inches), another 2 x 20 cm (1 x 8 inches), tape", p: ["Make a hoop from each strip of card, taping the ends together.", "Tape the small hoop to one end of the straw and the large hoop to the other.", "Launch it small hoop first with a gentle push: it glides far! The hoops work like wings."] }, at: "Glider contest", m: "paper, a tape measure or your steps", p: ["Make your hoop glider and a regular paper airplane.", "Throw each three times and measure which goes farther.", "Write the results in your logbook and earn today's stamp."], q: "What animal have you seen gliding in the sky?" },
es: { h: "En lo alto de un cerro, Nina y Leo vieron a una persona saltar con un ala enorme y flotar despacito hasta abajo, sin ningún motor. “¿Cómo no se cae?”, preguntó Leo. “Planea, como los buitres”, respondió el abuelo. “Así aprendieron los inventores a controlar el vuelo.”", t: "Los planeadores", f: "Un planeador es una aeronave sin motor que se desliza por el aire bajando despacio. En el siglo XIX, el inglés George Cayley descubrió las fuerzas que actúan sobre un avión y construyó planeadores. Después, el alemán Otto Lilienthal hizo unos 2.000 vuelos con planeadores que él mismo construyó.", x: "¡A Otto Lilienthal lo llamaron “el rey de los planeadores”. Los hermanos Wright estudiaron todo lo que él anotó antes de construir su avión!", s: ["Los planeadores suben usando corrientes de aire caliente que vienen del suelo, como hacen los buitres y las águilas.", "George Cayley diseñó un avión con ala fija, cola y cuerpo separados, muy parecido a los aviones de hoy.", "Todavía hoy existen pilotos de planeador, y pueden quedarse horas en el aire."], ex: { t: "Planeador de aros", m: "una pajita, una tira de cartulina de 2 x 12 cm, otra de 2 x 20 cm, cinta adhesiva", p: ["Haz un aro con cada tira de cartulina, uniendo las puntas con cinta.", "Pega el aro pequeño en una punta de la pajita y el grande en la otra.", "Lánzalo con el aro pequeño adelante, con un empujón suave: ¡planea lejos! Los aros funcionan como alas."] }, at: "Campeonato de planeadores", m: "papel, cinta métrica o tus pasos", p: ["Haz tu planeador de aros y un avión de papel común.", "Lanza cada uno tres veces y mide cuál llega más lejos.", "Anota los resultados en la libreta y gana el sello del día."], q: "¿Qué animal viste planeando en el cielo?" } },

{ e: "🛩️", art: { b: "🛩️", s: ["🚲", "🏖️", "🌬️", "🔧"], c: ["#4E3A1B", "#B08A4A"] },
pt: { h: "Leo quis saber quem tinha feito o primeiro avião com motor. Nina lembrou da viagem pelos Estados Unidos: “Os irmãos da bicicleta!”. O vovô sorriu: “Isso mesmo. E amanhã vamos conhecer um brasileiro que também entrou nessa história.”", t: "Os irmãos Wright e o Flyer", f: "Em 17 de dezembro de 1903, nos Estados Unidos, os irmãos Wright voaram com o Flyer, um avião com motor e hélices. Naquele dia, fizeram quatro voos. O primeiro durou 12 segundos, e o último, quase um minuto inteiro.", x: "O grande segredo dos Wright foi controlar o avião: eles torciam as pontas das asas para fazer curvas, uma ideia que tiveram observando pássaros!", s: ["O motor do Flyer foi construído por um mecânico da loja deles, porque nenhuma fábrica tinha um motor leve o suficiente.", "Os voos aconteceram em Kitty Hawk, um lugar com muito vento e areia macia para pousar.", "O Flyer decolava de um trilho de madeira, empurrado pelo vento contra."], ex: { t: "Vento que empurra", m: "um ventilador (com um adulto), uma folha de papel lisa, uma folha dobrada em curva", p: ["Ligue o ventilador na velocidade baixa.", "Segure a folha lisa de frente para o vento, depois de lado, e sinta a diferença do empurrão.", "Agora curve levemente a folha e segure-a quase deitada na frente do vento: ela quer subir! Os Wright testaram centenas de formatos assim."] }, at: "Asas que torcem", m: "um avião de papel, tesoura", p: ["Faça um avião de papel e corte duas abas pequenas na parte de trás de cada asa.", "Dobre uma aba para cima e a outra para baixo e lance.", "Para que lado ele virou? Anote na caderneta e carimbe."], q: "Por que você acha que é importante não desistir quando algo dá errado?" },
en: { h: "Leo wanted to know who built the first powered airplane. Nina remembered the trip across the United States: “The bicycle brothers!” Grandpa smiled: “That's right. And tomorrow we'll meet a Brazilian who's part of this story too.”", t: "The Wright brothers and the Flyer", f: "On December 17, 1903, in the United States, the Wright brothers flew the Flyer, an airplane with an engine and propellers. They made four flights that day. The first lasted 12 seconds and the last almost a full minute.", x: "The Wrights' big secret was control: they twisted the tips of the wings to turn, an idea they got from watching birds!", s: ["The Flyer's engine was built by a mechanic in their shop, because no factory made an engine light enough.", "The flights took place at Kitty Hawk, a windy place with soft sand for landing.", "The Flyer took off from a wooden rail, helped by a headwind."], ex: { t: "Pushing wind", m: "a fan (with a grown-up), a flat sheet of paper, a sheet bent into a curve", p: ["Turn the fan on low.", "Hold the flat sheet facing the wind, then sideways, and feel the difference in the push.", "Now curve the sheet slightly and hold it almost flat in front of the wind: it wants to rise! The Wrights tested hundreds of shapes like this."] }, at: "Twisting wings", m: "a paper airplane, scissors", p: ["Make a paper airplane and cut two small flaps at the back edge of each wing.", "Bend one flap up and the other down, then throw it.", "Which way did it turn? Write it in your logbook and stamp it."], q: "Why do you think it's important not to give up when something goes wrong?" },
es: { h: "Leo quiso saber quién había hecho el primer avión con motor. Nina se acordó del viaje por Estados Unidos: “¡Los hermanos de la bicicleta!”. El abuelo sonrió: “Así es. Y mañana vamos a conocer a un brasileño que también es parte de esta historia.”", t: "Los hermanos Wright y el Flyer", f: "El 17 de diciembre de 1903, en Estados Unidos, los hermanos Wright volaron con el Flyer, un avión con motor y hélices. Ese día hicieron cuatro vuelos. El primero duró 12 segundos, y el último, casi un minuto entero.", x: "¡El gran secreto de los Wright fue controlar el avión: torcían las puntas de las alas para girar, una idea que tuvieron observando pájaros!", s: ["El motor del Flyer lo construyó un mecánico de su taller, porque ninguna fábrica tenía un motor lo bastante liviano.", "Los vuelos fueron en Kitty Hawk, un lugar con mucho viento y arena blanda para aterrizar.", "El Flyer despegaba de un riel de madera, ayudado por el viento en contra."], ex: { t: "Viento que empuja", m: "un ventilador (con un adulto), una hoja de papel lisa, una hoja doblada en curva", p: ["Enciende el ventilador en velocidad baja.", "Sostén la hoja lisa de frente al viento, después de costado, y siente la diferencia del empujón.", "Ahora curva un poco la hoja y sostenla casi acostada frente al viento: ¡quiere subir! Los Wright probaron cientos de formas así."] }, at: "Alas que se tuercen", m: "un avión de papel, tijera", p: ["Haz un avión de papel y corta dos solapitas en la parte de atrás de cada ala.", "Dobla una solapa hacia arriba y la otra hacia abajo, y lánzalo.", "¿Hacia qué lado giró? Anótalo en la libreta y séllala."], q: "¿Por qué crees que es importante no rendirse cuando algo sale mal?" } },

{ e: "🎩", art: { b: "🛩️", s: ["🗼", "🎈", "⌚", "🏆"], c: ["#0B4F2C", "#2C8A5A"] },
pt: { h: "O vovô mostrou a foto de um homem bem baixinho, de chapéu e colarinho alto, ao lado de uma máquina esquisita que parecia feita de caixas. “Este é Alberto Santos-Dumont, mineiro, o pai da aviação para muitos brasileiros”, disse. Nina reparou no relógio de pulso dele.", t: "Santos-Dumont e o 14-Bis", f: "Em 23 de outubro de 1906, em Paris, Santos-Dumont voou com o 14-Bis diante de uma multidão e de juízes. O avião decolou sozinho, com as próprias rodas, sem trilho nem catapulta. Em novembro, ele voou 220 metros e bateu o primeiro recorde de aviação reconhecido oficialmente.", x: "Antes dos aviões, Santos-Dumont voou com dirigíveis. Em 1901, ele contornou a Torre Eiffel com um deles e ganhou um prêmio, que deu aos seus mecânicos e aos pobres de Paris!", s: ["Santos-Dumont nasceu em 1873, em Minas Gerais, numa cidade que hoje tem o nome dele.", "Ele criou o Demoiselle, um aviãozinho leve, e deixou os desenhos livres para qualquer um copiar.", "Por isso, no Brasil, muita gente o considera o verdadeiro pai da aviação, enquanto nos Estados Unidos esse título fica com os Wright."], ex: { t: "Ludião, o mergulhador", m: "uma garrafa PET cheia de água com tampa, uma tampa de caneta sem furo no topo, massinha", p: ["Coloque uma bolinha de massinha na ponta da tampa de caneta, para ela boiar em pé, quase afundando.", "Coloque a tampa dentro da garrafa cheia e feche bem.", "Aperte a garrafa: o mergulhador desce. Solte: ele sobe! Os dirigíveis controlam a subida e a descida de um jeito parecido, mudando o peso e o ar."] }, at: "Meu 14-Bis", m: "caixinhas de fósforo ou papelão, palitos, cola, lápis de cor", p: ["Monte um 14-Bis com caixinhas, imitando suas asas em forma de caixas.", "Pinte uma bandeirinha do Brasil nele.", "Desenhe um relógio de pulso no seu braço com caneta lavável, como o de Santos-Dumont, e carimbe a caderneta."], q: "Na sua opinião, quem merece o título de pai da aviação? Por quê?" },
en: { h: "Grandpa showed a photo of a very short man in a hat and high collar next to a strange machine that looked made of boxes. “This is Alberto Santos-Dumont, from Minas Gerais, whom many Brazilians call the father of aviation,” he said. Nina noticed his wristwatch.", t: "Santos-Dumont and the 14-Bis", f: "On October 23, 1906, in Paris, Santos-Dumont flew the 14-Bis in front of a crowd and official judges. The plane took off on its own wheels, with no rail or catapult. In November, he flew 220 meters (720 feet) and set the first officially recognized aviation record.", x: "Before airplanes, Santos-Dumont flew airships. In 1901, he flew one around the Eiffel Tower and won a prize, which he gave to his mechanics and the poor of Paris!", s: ["Santos-Dumont was born in 1873 in Minas Gerais, in a town that now bears his name.", "He created the Demoiselle, a light little airplane, and let anyone copy its designs for free.", "That's why many people in Brazil consider him the true father of aviation, while in the United States that title goes to the Wrights."], ex: { t: "Cartesian diver", m: "a plastic bottle full of water with a cap, a pen cap with no hole at the top, play dough", p: ["Put a little ball of play dough on the tip of the pen cap so it floats upright, almost sinking.", "Put the cap inside the full bottle and close it tightly.", "Squeeze the bottle: the diver sinks. Let go: it rises! Airships control going up and down in a similar way, by changing weight and air."] }, at: "My 14-Bis", m: "matchboxes or cardboard, sticks, glue, colored pencils", p: ["Build a 14-Bis with small boxes, copying its box-shaped wings.", "Paint a little Brazilian flag on it.", "Draw a wristwatch on your arm with washable marker, like Santos-Dumont's, and stamp your logbook."], q: "In your opinion, who deserves the title of father of aviation? Why?" },
es: { h: "El abuelo mostró la foto de un hombre muy bajito, con sombrero y cuello alto, al lado de una máquina rara que parecía hecha de cajas. “Este es Alberto Santos-Dumont, de Minas Gerais, el padre de la aviación para muchos brasileños”, dijo. Nina notó su reloj de pulsera.", t: "Santos-Dumont y el 14-Bis", f: "El 23 de octubre de 1906, en París, Santos-Dumont voló con el 14-Bis ante una multitud y jueces oficiales. El avión despegó solo, con sus propias ruedas, sin riel ni catapulta. En noviembre voló 220 metros y logró el primer récord de aviación reconocido oficialmente.", x: "¡Antes de los aviones, Santos-Dumont voló en dirigibles. En 1901 rodeó la Torre Eiffel con uno de ellos y ganó un premio, que les dio a sus mecánicos y a los pobres de París!", s: ["Santos-Dumont nació en 1873 en Minas Gerais, en una ciudad que hoy lleva su nombre.", "Creó el Demoiselle, un avioncito liviano, y dejó sus planos libres para que cualquiera los copiara.", "Por eso, en Brasil, mucha gente lo considera el verdadero padre de la aviación, mientras que en Estados Unidos ese título es de los Wright."], ex: { t: "Ludión, el buzo", m: "una botella de plástico llena de agua con tapa, un capuchón de bolígrafo sin agujero arriba, plastilina", p: ["Pon una bolita de plastilina en la punta del capuchón para que flote de pie, casi hundiéndose.", "Mete el capuchón en la botella llena y ciérrala bien.", "Aprieta la botella: el buzo baja. Suelta: ¡sube! Los dirigibles controlan la subida y la bajada de una forma parecida, cambiando el peso y el aire."] }, at: "Mi 14-Bis", m: "cajitas de fósforos o cartón, palitos, pegamento, lápices de colores", p: ["Arma un 14-Bis con cajitas, imitando sus alas en forma de caja.", "Píntale una banderita de Brasil.", "Dibuja un reloj de pulsera en tu brazo con marcador lavable, como el de Santos-Dumont, y sella tu libreta."], q: "En tu opinión, ¿quién merece el título de padre de la aviación? ¿Por qué?" } },

{ e: "⬆️", art: { b: "✈️", s: ["⬆️", "⬇️", "➡️", "⬅️"], c: ["#1B3A6B", "#3A6AB0"] },
pt: { h: "Leo puxou um lado da corda e Nina puxou o outro, num cabo de guerra. Ninguém saía do lugar. “Num avião em voo, acontece um cabo de guerra parecido”, disse o vovô. “Só que são quatro forças puxando ao mesmo tempo.”", t: "As quatro forças do voo", f: "Quatro forças agem num avião: o peso puxa para baixo, a sustentação empurra para cima, a tração (do motor) puxa para a frente e o arrasto (a resistência do ar) puxa para trás. Para voar, a sustentação precisa vencer o peso, e a tração precisa vencer o arrasto.", x: "Quando o avião voa reto e na mesma velocidade, as quatro forças estão equilibradas, como num cabo de guerra empatado!", s: ["As asas são as responsáveis pela sustentação.", "Os motores e as hélices produzem a tração.", "Os aviões têm formato liso e arredondado para diminuir o arrasto, como um peixe na água."], ex: { t: "Avião de papel com peso", m: "um avião de papel, clipes de papel", p: ["Lance o avião de papel do jeito normal e veja como ele voa.", "Coloque um clipe no bico e lance de novo. Depois mude o clipe para a parte de trás.", "Com peso na frente ele mergulha, com peso atrás ele empina! O equilíbrio das forças muda tudo."] }, at: "Cartaz das quatro forças", m: "papel, lápis de cor", p: ["Desenhe um avião grande no meio da folha.", "Desenhe quatro setas coloridas: para cima (sustentação), para baixo (peso), para a frente (tração) e para trás (arrasto).", "Escreva o nome de cada força e carimbe a caderneta."], q: "Que outras coisas você conhece que fazem “cabo de guerra” com o ar?" },
en: { h: "Leo pulled one end of the rope and Nina pulled the other in a tug-of-war. Nobody moved. “A similar tug-of-war happens to a plane in flight,” Grandpa said. “Except there are four forces pulling at the same time.”", t: "The four forces of flight", f: "Four forces act on an airplane: weight pulls down, lift pushes up, thrust (from the engines) pulls forward and drag (air resistance) pulls back. To fly, lift has to beat weight and thrust has to beat drag.", x: "When a plane flies straight at a steady speed, the four forces are balanced, like a tied tug-of-war!", s: ["The wings are responsible for lift.", "Engines and propellers produce thrust.", "Airplanes have smooth, rounded shapes to reduce drag, like a fish in water."], ex: { t: "Paper airplane with weight", m: "a paper airplane, paper clips", p: ["Throw the paper airplane normally and see how it flies.", "Put a clip on the nose and throw it again. Then move the clip to the back.", "With weight in front it dives; with weight in back it pitches up! Balancing the forces changes everything."] }, at: "Four forces poster", m: "paper, colored pencils", p: ["Draw a big airplane in the middle of the page.", "Draw four colored arrows: up (lift), down (weight), forward (thrust) and back (drag).", "Label each force and stamp your logbook."], q: "What other things do you know that play “tug-of-war” with the air?" },
es: { h: "Leo tiró de una punta de la cuerda y Nina de la otra, en una cinchada. Nadie se movía. “En un avión en vuelo pasa una cinchada parecida”, dijo el abuelo. “Solo que son cuatro fuerzas tirando al mismo tiempo.”", t: "Las cuatro fuerzas del vuelo", f: "Cuatro fuerzas actúan sobre un avión: el peso tira hacia abajo, la sustentación empuja hacia arriba, el empuje (del motor) tira hacia adelante y la resistencia del aire tira hacia atrás. Para volar, la sustentación tiene que vencer al peso, y el empuje tiene que vencer a la resistencia.", x: "¡Cuando el avión vuela recto y a la misma velocidad, las cuatro fuerzas están equilibradas, como una cinchada empatada!", s: ["Las alas son las responsables de la sustentación.", "Los motores y las hélices producen el empuje.", "Los aviones tienen forma lisa y redondeada para reducir la resistencia, como un pez en el agua."], ex: { t: "Avión de papel con peso", m: "un avión de papel, clips", p: ["Lanza el avión de papel normalmente y mira cómo vuela.", "Pon un clip en la punta y lánzalo otra vez. Después pasa el clip a la parte de atrás.", "Con peso adelante se clava; con peso atrás se encabrita. ¡El equilibrio de las fuerzas lo cambia todo!"] }, at: "Cartel de las cuatro fuerzas", m: "papel, lápices de colores", p: ["Dibuja un avión grande en el medio de la hoja.", "Dibuja cuatro flechas de colores: hacia arriba (sustentación), hacia abajo (peso), hacia adelante (empuje) y hacia atrás (resistencia).", "Escribe el nombre de cada fuerza y sella la libreta."], q: "¿Qué otras cosas conoces que hacen una “cinchada” con el aire?" } },

{ e: "🪽", art: { b: "🪽", s: ["🌬️", "💧", "🥄", "⬆️"], c: ["#0B3A5A", "#2C8AC2"] },
pt: { h: "Na janela do avião, numa viagem de férias, Nina tinha reparado que a asa era grossa na frente e fininha atrás, e meio curvada. “Por que ela não é retinha?”, perguntou agora. O vovô pegou uma colher e foi até a pia. “Vou mostrar um truque do ar e da água”, disse.", t: "O segredo das asas", f: "A asa do avião é curvada em cima e um pouco inclinada. Quando o avião anda rápido, a asa empurra o ar para baixo, e o ar empurra a asa para cima. Ao mesmo tempo, o ar que passa por cima da asa fica com menos pressão do que o de baixo. Tudo isso gera a sustentação.", x: "As asas de um avião grande podem envergar vários metros para cima durante o voo! Elas são flexíveis de propósito, para aguentar o vento sem quebrar.", s: ["Quanto mais rápido o avião, mais sustentação as asas produzem.", "Os pássaros também têm asas curvas, e foi observando-os que os inventores entenderam o formato.", "O formato da asa visto de lado se chama perfil aerodinâmico."], ex: { t: "A colher puxada", m: "uma colher, uma torneira com filete de água", p: ["Abra a torneira num filete fino e contínuo.", "Segure a colher bem solta pela ponta do cabo e aproxime a parte de trás curvada do filete.", "A colher é puxada para dentro da água! O fluido segue a curva e puxa a colher, parecido com o ar seguindo a curva da asa."] }, at: "Perfil da asa", m: "papel, régua, lápis de cor", p: ["Desenhe uma asa vista de lado: grossa e arredondada na frente, fininha atrás.", "Desenhe setas mostrando o ar passando por cima e por baixo, e o ar sendo empurrado para baixo atrás da asa.", "Desenhe uma seta grande para cima: a sustentação! Carimbe a caderneta."], q: "Onde mais você já viu uma forma parecida com a de uma asa?" },
en: { h: "Looking out the plane window on a vacation trip, Nina had noticed that the wing was thick in front, thin in back and a little curved. “Why isn't it straight?” she asked now. Grandpa grabbed a spoon and went to the sink. “I'll show you a trick with air and water,” he said.", t: "The secret of wings", f: "An airplane wing is curved on top and tilted slightly. When the plane moves fast, the wing pushes air down, and the air pushes the wing up. At the same time, the air flowing over the top of the wing has lower pressure than the air below. All of this creates lift.", x: "The wings of a big airplane can bend several meters upward in flight! They're flexible on purpose, so they can handle the wind without breaking.", s: ["The faster the plane goes, the more lift the wings produce.", "Birds also have curved wings, and inventors understood the shape by watching them.", "The shape of a wing seen from the side is called an airfoil."], ex: { t: "The pulled spoon", m: "a spoon, a faucet with a thin stream of water", p: ["Turn the faucet on to a thin, steady stream.", "Hold the spoon loosely by the tip of the handle and bring its curved back close to the stream.", "The spoon gets pulled into the water! The fluid follows the curve and pulls the spoon, similar to air following the curve of a wing."] }, at: "Wing profile", m: "paper, ruler, colored pencils", p: ["Draw a wing seen from the side: thick and rounded in front, thin in back.", "Draw arrows showing air flowing over and under it, and air pushed down behind the wing.", "Draw a big upward arrow: lift! Stamp your logbook."], q: "Where else have you seen a shape like a wing?" },
es: { h: "Mirando por la ventanilla del avión en unas vacaciones, Nina había notado que el ala era gruesa adelante, finita atrás y un poco curvada. “¿Por qué no es recta?”, preguntó ahora. El abuelo tomó una cuchara y fue hasta la pileta. “Les voy a mostrar un truco del aire y del agua”, dijo.", t: "El secreto de las alas", f: "El ala del avión es curvada arriba y está un poco inclinada. Cuando el avión va rápido, el ala empuja el aire hacia abajo, y el aire empuja el ala hacia arriba. Al mismo tiempo, el aire que pasa por encima del ala tiene menos presión que el de abajo. Todo eso genera la sustentación.", x: "¡Las alas de un avión grande pueden curvarse varios metros hacia arriba durante el vuelo! Son flexibles a propósito, para aguantar el viento sin romperse.", s: ["Cuanto más rápido va el avión, más sustentación producen las alas.", "Los pájaros también tienen alas curvas, y observándolos los inventores entendieron la forma.", "La forma del ala vista de costado se llama perfil aerodinámico."], ex: { t: "La cuchara atraída", m: "una cuchara, una canilla con un chorrito de agua", p: ["Abre la canilla en un chorrito fino y continuo.", "Sostén la cuchara floja por la punta del mango y acerca su parte de atrás curvada al chorro.", "¡La cuchara es atraída hacia el agua! El líquido sigue la curva y tira de la cuchara, parecido al aire siguiendo la curva del ala."] }, at: "Perfil del ala", m: "papel, regla, lápices de colores", p: ["Dibuja un ala vista de costado: gruesa y redondeada adelante, finita atrás.", "Dibuja flechas mostrando el aire pasando por arriba y por abajo, y el aire empujado hacia abajo detrás del ala.", "Dibuja una flecha grande hacia arriba: ¡la sustentación! Sella tu libreta."], q: "¿Dónde más viste una forma parecida a la de un ala?" } },

{ e: "🌀", art: { b: "🌀", s: ["✈️", "🌬️", "🎐", "⚙️"], c: ["#2A1B4E", "#6A4AB0"] },
pt: { h: "Leo segurou um cata-vento na frente do ventilador, e ele girou sem parar. “E se fosse ao contrário?”, perguntou Nina. “Se a gente girasse o cata-vento bem rápido, ele empurraria o ar?” O vovô arregalou os olhos: “Você acabou de inventar a hélice!”", t: "A hélice", f: "Uma hélice é como várias asinhas que giram. Cada pá é curvada e inclinada, então, quando gira, empurra o ar para trás. Como resposta, o ar empurra o avião para a frente. Esse empurrão se chama tração.", x: "A hélice é uma asa girando: a mesma força que levanta a asa puxa o avião para a frente!", s: ["Os primeiros aviões, como o Flyer e o 14-Bis, usavam hélices movidas por motores a gasolina.", "Muitos aviões de hoje ainda usam hélices, principalmente os menores e os que fazem voos curtos.", "Os barcos e os ventiladores também usam hélices."], ex: { t: "Cata-vento", m: "um quadrado de papel (15 x 15 cm), tesoura, um alfinete ou tachinha, um lápis com borracha (com um adulto)", p: ["Corte o quadrado das pontas em direção ao centro, sem chegar no meio.", "Dobre uma ponta sim, uma não, até o centro, e prenda com o alfinete na borracha do lápis (um adulto ajuda).", "Sopre ou corra com ele: as pás curvas transformam o vento em giro. A hélice faz o caminho contrário: o giro vira vento!"] }, at: "Hélice de muitas pás", m: "papel, lápis de cor", p: ["Pesquise com um adulto fotos de aviões com 2, 3, 4 e até 8 pás na hélice.", "Desenhe uma hélice com o número de pás que você achar mais bonito.", "Cole na caderneta e carimbe."], q: "Onde mais você já viu algo girando para empurrar ar ou água?" },
en: { h: "Leo held a pinwheel in front of the fan, and it spun and spun. “What if it were the other way around?” Nina asked. “If we spun the pinwheel really fast, would it push the air?” Grandpa's eyes widened: “You just invented the propeller!”", t: "The propeller", f: "A propeller is like several little wings that spin. Each blade is curved and tilted, so as it spins it pushes air backward. In response, the air pushes the plane forward. That push is called thrust.", x: "A propeller is a spinning wing: the same force that lifts a wing pulls the plane forward!", s: ["The first airplanes, like the Flyer and the 14-Bis, used propellers driven by gasoline engines.", "Many planes today still use propellers, especially smaller ones and those that make short flights.", "Boats and fans use propellers too."], ex: { t: "Pinwheel", m: "a paper square (15 x 15 cm, or 6 x 6 inches), scissors, a pin or thumbtack, a pencil with an eraser (with a grown-up)", p: ["Cut from each corner toward the center without reaching the middle.", "Fold every other point into the center and pin it to the pencil eraser (a grown-up helps).", "Blow on it or run with it: the curved blades turn wind into spinning. A propeller does the opposite: spinning becomes wind!"] }, at: "Many-bladed propeller", m: "paper, colored pencils", p: ["With a grown-up, look up photos of planes with 2, 3, 4 and even 8 propeller blades.", "Draw a propeller with the number of blades you think looks best.", "Glue it into your logbook and stamp it."], q: "Where else have you seen something spinning to push air or water?" },
es: { h: "Leo sostuvo un molinete frente al ventilador, y giró sin parar. “¿Y si fuera al revés?”, preguntó Nina. “Si hiciéramos girar el molinete muy rápido, ¿empujaría el aire?” El abuelo abrió grandes los ojos: “¡Acabas de inventar la hélice!”", t: "La hélice", f: "Una hélice es como varias alitas que giran. Cada pala está curvada e inclinada, así que, al girar, empuja el aire hacia atrás. En respuesta, el aire empuja el avión hacia adelante. Ese empujón se llama empuje o tracción.", x: "¡La hélice es un ala que gira: la misma fuerza que levanta el ala tira del avión hacia adelante!", s: ["Los primeros aviones, como el Flyer y el 14-Bis, usaban hélices movidas por motores a nafta.", "Muchos aviones de hoy todavía usan hélices, sobre todo los más pequeños y los de vuelos cortos.", "Los barcos y los ventiladores también usan hélices."], ex: { t: "Molinete", m: "un cuadrado de papel (15 x 15 cm), tijera, un alfiler o chinche, un lápiz con goma (con un adulto)", p: ["Corta el cuadrado desde las puntas hacia el centro, sin llegar al medio.", "Dobla una punta sí y una no hasta el centro, y sujétalas con el alfiler en la goma del lápiz (un adulto ayuda).", "Sopla o corre con él: las palas curvas convierten el viento en giro. ¡La hélice hace lo contrario: el giro se vuelve viento!"] }, at: "Hélice de muchas palas", m: "papel, lápices de colores", p: ["Busca con un adulto fotos de aviones con 2, 3, 4 y hasta 8 palas en la hélice.", "Dibuja una hélice con el número de palas que te parezca más lindo.", "Pégala en la libreta y séllala."], q: "¿Dónde más viste algo que gira para empujar aire o agua?" } },

{ e: "🔥", art: { b: "🛫", s: ["🔥", "💨", "🎈", "⚙️"], c: ["#4E1B0B", "#C24A2C"] },
pt: { h: "No aeroporto, Leo ficou impressionado com o barulho dos motores enormes. “Não tem hélice!”, reparou. “Tem, mas fica escondida lá dentro”, disse o vovô. “E esse motor funciona com o mesmo segredo de uma bexiga que você enche e solta.”", t: "O motor a jato", f: "O motor a jato puxa muito ar pela frente, aperta esse ar, mistura com combustível e queima. Os gases quentes saem pela traseira em altíssima velocidade e empurram o avião para a frente, assim como o ar que escapa de uma bexiga a faz voar.", x: "O primeiro avião a jato voou em 1939, na Alemanha. Hoje, quase todos os aviões grandes de passageiros usam motores a jato!", s: ["O inglês Frank Whittle e o alemão Hans von Ohain inventaram motores a jato quase ao mesmo tempo, sem saber um do outro.", "Nos motores modernos, um ventilador gigante na frente empurra a maior parte do ar por fora, o que deixa o motor mais silencioso e econômico.", "Um motor de avião grande pode ter um ventilador maior que a altura de um adulto."], ex: { t: "Carrinho a jato", m: "um carrinho de brinquedo leve, uma bexiga, um canudo, fita adesiva", p: ["Prenda o canudo dentro da boca da bexiga com fita, bem vedado.", "Prenda a bexiga em cima do carrinho, com o canudo apontando para trás.", "Encha a bexiga soprando pelo canudo, tampe com o dedo, coloque no chão e solte: o carrinho dispara para a frente!"] }, at: "Por dentro do motor", m: "papel, lápis de cor", p: ["Desenhe um motor a jato cortado ao meio, como um sanduíche.", "Pinte de azul o ar frio entrando, de laranja o fogo no meio e de cinza os gases saindo atrás.", "Escreva as etapas: puxa, aperta, queima, sopra! Carimbe a caderneta."], q: "O que você acha que faz mais barulho: um avião a jato ou um a hélice?" },
en: { h: "At the airport, Leo was amazed by the noise of the huge engines. “They don't have propellers!” he noticed. “They do, but they're hidden inside,” Grandpa said. “And that engine works with the same secret as a balloon you blow up and let go.”", t: "The jet engine", f: "A jet engine sucks in lots of air at the front, squeezes it, mixes it with fuel and burns it. The hot gases shoot out the back at very high speed and push the plane forward, just like the air escaping from a balloon makes it fly.", x: "The first jet airplane flew in 1939, in Germany. Today, almost all large passenger planes use jet engines!", s: ["Englishman Frank Whittle and German Hans von Ohain invented jet engines at almost the same time, without knowing about each other.", "In modern engines, a giant fan at the front pushes most of the air around the outside, which makes the engine quieter and more efficient.", "A big airplane engine can have a fan taller than a grown-up."], ex: { t: "Jet car", m: "a light toy car, a balloon, a straw, tape", p: ["Tape the straw inside the neck of the balloon, sealing it well.", "Tape the balloon on top of the car with the straw pointing backward.", "Blow up the balloon through the straw, cover the end with your finger, set the car down and let go: it zooms forward!"] }, at: "Inside the engine", m: "paper, colored pencils", p: ["Draw a jet engine cut in half, like a sandwich.", "Color the cold air coming in blue, the fire in the middle orange and the gases going out the back gray.", "Write the steps: suck, squeeze, bang, blow! Stamp your logbook."], q: "Which do you think is louder: a jet plane or a propeller plane?" },
es: { h: "En el aeropuerto, Leo quedó impresionado con el ruido de los motores enormes. “¡No tienen hélice!”, notó. “Sí tienen, pero está escondida adentro”, dijo el abuelo. “Y ese motor funciona con el mismo secreto que un globo que inflas y sueltas.”", t: "El motor a reacción", f: "El motor a reacción aspira mucho aire por adelante, lo aprieta, lo mezcla con combustible y lo quema. Los gases calientes salen por atrás a altísima velocidad y empujan el avión hacia adelante, igual que el aire que se escapa de un globo lo hace volar.", x: "¡El primer avión a reacción voló en 1939, en Alemania. Hoy casi todos los aviones grandes de pasajeros usan motores a reacción!", s: ["El inglés Frank Whittle y el alemán Hans von Ohain inventaron motores a reacción casi al mismo tiempo, sin saber uno del otro.", "En los motores modernos, un ventilador gigante adelante empuja la mayor parte del aire por fuera, lo que hace el motor más silencioso y económico.", "Un motor de avión grande puede tener un ventilador más alto que un adulto."], ex: { t: "Autito a reacción", m: "un autito de juguete liviano, un globo, una pajita, cinta adhesiva", p: ["Pega la pajita dentro de la boca del globo con cinta, bien sellada.", "Pega el globo encima del autito, con la pajita apuntando hacia atrás.", "Infla el globo soplando por la pajita, tápala con el dedo, pon el autito en el piso y suéltalo: ¡sale disparado hacia adelante!"] }, at: "Por dentro del motor", m: "papel, lápices de colores", p: ["Dibuja un motor a reacción cortado al medio, como un sándwich.", "Pinta de azul el aire frío que entra, de naranja el fuego del medio y de gris los gases que salen atrás.", "Escribe los pasos: ¡aspira, aprieta, quema, sopla! Sella tu libreta."], q: "¿Qué crees que hace más ruido: un avión a reacción o uno a hélice?" } },
];
